//! Structural skew-normalization exits and crowded-side open blocks for gTrade.

use hedger_core::InstrumentKey;
use perp_core::snapshot::VenueSlug;
use perp_core::StateVectorV1;
use perp_venues::{check_skew_normalized, estimate_open_costs, oi_skew_ratio, TradingVariablesSnapshot};

use crate::directional_follow::{DirectionalLegOutcome, EffectiveDirectionalParams};
use crate::types::{ExecutionRouterConfig, GainsMarketCostsConfig};

/// Directional exit policy for in-position legs.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum DirectionalExitMode {
    /// Close on opposite `r_hat` sign past flip threshold (Chronos default).
    #[default]
    ChronosFlip,
    /// Close when OI skew normalizes toward balanced (structural strategy).
    StructuralSkewExit,
}

impl DirectionalExitMode {
    pub fn from_str(s: &str) -> Self {
        match s.trim().to_ascii_lowercase().as_str() {
            "structural_skew_exit" | "structural" | "skew_exit" => Self::StructuralSkewExit,
            _ => Self::ChronosFlip,
        }
    }
}

/// Structural exit tuning (skew band, borrow-bleed tightening).
#[derive(Clone, Debug, serde::Serialize, serde::Deserialize)]
#[serde(default)]
pub struct StructuralExitConfig {
    pub exit_skew_band: f64,
    /// Tighten exit band by this factor when holding_fee drag is elevated.
    pub borrow_bleed_exit_tighten_frac: f64,
    pub borrow_bleed_bps_per_hour: f64,
}

impl Default for StructuralExitConfig {
    fn default() -> Self {
        Self {
            exit_skew_band: 0.08,
            borrow_bleed_exit_tighten_frac: 0.5,
            borrow_bleed_bps_per_hour: 50.0,
        }
    }
}

/// Whether an open on the prospective side should be blocked (crowded or no depth).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum StructuralOpenBlock {
    None,
    CrowdedSide,
    DepthUnavailable,
}

impl StructuralOpenBlock {
    pub fn skip_reason(&self) -> Option<&'static str> {
        match self {
            Self::None => None,
            Self::CrowdedSide => Some("gains_crowded_side_blocked"),
            Self::DepthUnavailable => Some("gains_depth_unavailable"),
        }
    }
}

/// Evaluate crowded-side block and depth availability for a prospective open.
pub fn check_structural_open_block(
    costs: &GainsMarketCostsConfig,
    audit: &perp_venues::GainsMarketCostAudit,
    telemetry_only: bool,
) -> StructuralOpenBlock {
    if !costs.enabled {
        return StructuralOpenBlock::None;
    }
    if !audit.depth_available {
        return StructuralOpenBlock::DepthUnavailable;
    }
